from __future__ import annotations

import importlib.util
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch
import unittest

SPEC = importlib.util.spec_from_file_location(
    "commit_hygiene", Path(__file__).with_name("check_commit_hygiene.py")
)
assert SPEC and SPEC.loader
module = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(module)


class CommitHygieneTests(unittest.TestCase):
    def check_commit_fields(self, message: str, *, author_name="Connor Avila", author_email="owner@example.invalid"):
        fields = "\0".join((author_name, author_email, "Connor Avila", "owner@example.invalid", message))
        with patch.object(module, "git", return_value=fields.encode()):
            module.check_commit("0123456789abcdef", "owner@example.invalid")

    def test_rejects_wrong_author_or_committer_email(self):
        for fields, expected in (
            ("Connor Avila\0bad@example.invalid\0Connor Avila\0owner@example.invalid\0safe", "author-email"),
            ("Connor Avila\0owner@example.invalid\0Connor Avila\0bad@example.invalid\0safe", "committer-email"),
        ):
            with self.subTest(expected=expected), patch.object(module, "git", return_value=fields.encode()):
                with self.assertRaises(module.Refusal) as caught:
                    module.check_commit("0123456789abcdef", "owner@example.invalid")
                self.assertEqual(caught.exception.rule, expected)

    def test_rejects_non_owner_name_and_ai_attribution(self):
        with self.assertRaises(module.Refusal) as caught:
            self.check_commit_fields("safe", author_name="Other Person")
        self.assertEqual(caught.exception.rule, "author-name")
        for message in ("generated by a tool", "Claude assisted change"):
            with self.subTest(message=message):
                with self.assertRaises(module.Refusal) as caught:
                    self.check_commit_fields(message)
                self.assertEqual(caught.exception.rule, "prohibited-message-marker")

    def test_rejects_absolute_user_path_in_tracked_tree(self):
        with patch.object(module.subprocess, "run", return_value=SimpleNamespace(returncode=0)):
            with self.assertRaises(module.Refusal) as caught:
                module.check_tracked_paths(["0123456789abcdef"])
        self.assertEqual(caught.exception.rule, "tracked-user-path")

    def test_cursor_word_boundary_does_not_reject_unrelated_words(self):
        self.check_commit_fields("Search cursorily for an unrelated issue")


if __name__ == "__main__":
    unittest.main()
